(6822722, 1026062, 143116, '<td valign="top">Amongst all the lovely color shots a BW does not convey the lusciousness of dessert.</td>', 'Amongst all the lovely color shots a BW does not convey the lusciousness of dessert.', '2012-07-20 15:32:14.000000', NULL, 1),
