(6822727, 1025939, 143116, '<td valign="top">Just perfect</td>', 'Just perfect', '2012-07-20 15:33:52.000000', NULL, 1),
(6822765, 1025957, 149507, '<td valign="top">The background is distracting and competes for attention with the main subject. Highlights are blown out and the saturation seems overdone.</td>', 'The background is distracting and competes for attention with the main subject. Highlights are blown out and the saturation seems overdone.', '2012-07-20 15:50:04.000000', NULL, 1),
(6822773, 1025635, 143116, '<td valign="top">I''m afraid I''m not cut out for this kind of pictures. I look, look again, feel a little puzzled, think I recognize something,start doubtng again and in the end I scroll to the next picture, a little frustrated...</td>', 'I''m afraid I''m not cut out for this kind of pictures. I look, look again, feel a little puzzled, think I recognize something,start doubtng again and in the end I scroll to the next picture, a little frustrated...', '2012-07-20 15:58:21.000000', NULL, 1),
