(6826090, 1026080, 141542, '<td valign="top">I think the placement of the box is a little weird, but I like the concept.</td>', 'I think the placement of the box is a little weird, but I like the concept.', '2012-07-24 10:48:34.000000', NULL, 1),
(6826091, 1026067, 141542, '<td valign="top">Colors are beautiful, unfortunately, I think the vignette creeps into the focal point a bit too much.</td>', 'Colors are beautiful, unfortunately, I think the vignette creeps into the focal point a bit too much.', '2012-07-24 10:49:19.000000', NULL, 1),
(6826092, 1026061, 141542, '<td valign="top">Excellent.</td>', 'Excellent.', '2012-07-24 10:49:27.000000', NULL, 1),
(6826093, 1025925, 141542, '<td valign="top">An interesting crop, but it might have been better from a lower, less human angle.  Seems a bit dark as well.</td>', 'An interesting crop, but it might have been better from a lower, less human angle.  Seems a bit dark as well.', '2012-07-24 10:50:01.000000', NULL, 1),
(6826095, 1025802, 141542, '<td valign="top">Uninteresting angle and the image appears oddly tilted.  The lack of space near the top of the composition also causes issues.</td>', 'Uninteresting angle and the image appears oddly tilted.  The lack of space near the top of the composition also causes issues.', '2012-07-24 10:51:05.000000', NULL, 1),
(6826096, 1025837, 141542, '<td valign="top">I think the actual colors of this would be nice to see, but this isn''t a bad shot at all.</td>', 'I think the actual colors of this would be nice to see, but this isn''t a bad shot at all.', '2012-07-24 10:51:26.000000', NULL, 1),
(6826097, 1025939, 141542, '<td valign="top">Excellent.  This is perfectly acceptable product-style photography, with a twist of vintage beauty.</td>', 'Excellent.  This is perfectly acceptable product-style photography, with a twist of vintage beauty.', '2012-07-24 10:52:00.000000', NULL, 1),
(6826098, 1025822, 141542, '<td valign="top">Well-lit eyes would have been nice.  Not bad though, I like the crop.</td>', 'Well-lit eyes would have been nice.  Not bad though, I like the crop.', '2012-07-24 10:53:05.000000', NULL, 1),
(6826099, 1025982, 141542, '<td valign="top">There''s a good moment present on the face, but I wish at least one portion of this image was in focus.</td>', 'There''s a good moment present on the face, but I wish at least one portion of this image was in focus.', '2012-07-24 10:54:08.000000', NULL, 1),
(6826102, 1026078, 141542, '<td valign="top">A nice setup, but it''s underexposed, and the composition favors the right side of the frame.  A little pop, and proper framing, would''ve made this much better.</td>', 'A nice setup, but it''s underexposed, and the composition favors the right side of the frame.  A little pop, and proper framing, would''ve made this much better.', '2012-07-24 10:55:53.000000', NULL, 1),
(6826103, 1026068, 141542, '<td valign="top">Hilarious concept.  I wish it was a little clearer without seeing the title, but the creativity factor is extremely high here.  Well done!</td>', 'Hilarious concept.  I wish it was a little clearer without seeing the title, but the creativity factor is extremely high here.  Well done!', '2012-07-24 10:56:46.000000', NULL, 1),
(6826104, 1025730, 141542, '<td valign="top">Looks delicious!  I don''t know about the notes belonging there, but I think the overall quality of the setup overshadows the odd juxtaposition of items.</td>', 'Looks delicious!  I don''t know about the notes belonging there, but I think the overall quality of the setup overshadows the odd juxtaposition of items.', '2012-07-24 10:57:45.000000', NULL, 1);
INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6826105, 1026070, 141542, '<td valign="top">Beautiful abstract.  Contemporary and tasteful.</td>', 'Beautiful abstract.  Contemporary and tasteful.', '2012-07-24 10:58:06.000000', NULL, 1),
(6826106, 1026010, 141542, '<td valign="top">I think this might''ve been better had the entire scene been in focus, but it''s a good image and idea.</td>', 'I think this might''ve been better had the entire scene been in focus, but it''s a good image and idea.', '2012-07-24 10:58:38.000000', NULL, 1),
(6826108, 1026076, 141542, '<td valign="top">Not a fan of the processing style, personally, but I''m a huge fan of the image and it''s content.  Great stuff!</td>', 'Not a fan of the processing style, personally, but I''m a huge fan of the image and it''s content.  Great stuff!', '2012-07-24 10:59:13.000000', NULL, 1),
(6826110, 1025958, 141542, '<td valign="top">This is another instance of an image that would benefit from greater depth of field, in my opinion, but it''s a really well put together shot, and that deserves a sincere compliment.</td>', 'This is another instance of an image that would benefit from greater depth of field, in my opinion, but it''s a really well put together shot, and that deserves a sincere compliment.', '2012-07-24 11:00:30.000000', NULL, 1),
(6826111, 1026035, 141542, '<td valign="top">Great image.  Perfectly balanced.</td>', 'Great image.  Perfectly balanced.', '2012-07-24 11:01:05.000000', NULL, 1),
(6826113, 1025941, 141542, '<td valign="top">Very well composed, although not terribly exciting.  Nice image.</td>', 'Very well composed, although not terribly exciting.  Nice image.', '2012-07-24 11:02:32.000000', NULL, 1),
(6826114, 1026024, 141542, '<td valign="top">Interesting combination of colors.  Lots of strawberries in this challenge.</td>', 'Interesting combination of colors.  Lots of strawberries in this challenge.', '2012-07-24 11:02:59.000000', NULL, 1),
(6826115, 1026077, 141542, '<td valign="top">Good stuff.  Wish the bottom of the composition had a little more room.</td>', 'Good stuff.  Wish the bottom of the composition had a little more room.', '2012-07-24 11:03:29.000000', NULL, 1),
(6826116, 1025684, 141542, '<td valign="top">Perfectly fine shot.</td>', 'Perfectly fine shot.', '2012-07-24 11:03:51.000000', NULL, 1),
(6826117, 1025994, 141542, '<td valign="top">The shoes and the outfit kind of kill the scene for me, but it''s definitely well executed technically.</td>', 'The shoes and the outfit kind of kill the scene for me, but it''s definitely well executed technically.', '2012-07-24 11:04:37.000000', NULL, 1),
(6826118, 1026017, 141542, '<td valign="top">Hahahha. Donuts indeed.</td>', 'Hahahha. Donuts indeed.', '2012-07-24 11:04:52.000000', NULL, 1),
(6826119, 1025956, 141542, '<td valign="top">I like the idea, but the tilt kind of hurts the concept.</td>', 'I like the idea, but the tilt kind of hurts the concept.', '2012-07-24 11:06:07.000000', NULL, 1),
(6826120, 1026010, 43463, '<td valign="top">Voted earlier coming back to comment.<br/> <br/>I like how you included a person in the shot with that great expression! It captures the anticipation of getting the first bite. The arrangement and decoration on and around the cake looks very tasty. I do have two suggestions on how to further improve the visual appeal. First off I suggest to boast the contrast just a tad - the whipped cream puffs on the top of the cake needs a bit more contrast for the swirl pattern to pop - some areas have the highlights to high that I cannot see the details. Just a small boast would also increase the depth in the overall image resulting in all elements more defined with the difference between light and shadow. Lastly, I think it would show off the girl''s expression better if you had the model stand a little higher. That way the cropped version would just have the mouth only and it would not be partially obscured by the strawberries.</td>', 'Voted earlier coming back to comment. I like how you included a person in the shot with that great expression! It captures the anticipation of getting the first bite. The arrangement and decoration on and around the cake looks very tasty. I do have two suggestions on how to further improve the visual appeal. First off I suggest to boast the contrast just a tad - the whipped cream puffs on the top of the cake needs a bit more contrast for the swirl pattern to pop - some areas have the highlights to high that I cannot see the details. Just a small boast would also increase the depth in the overall image resulting in all elements more defined with the difference between light and shadow. Lastly, I think it would show off the girl''s expression better if you had the model stand a little higher. That way the cropped version would just have the mouth only and it would not be partially obscured by the strawberries.', '2012-07-24 11:08:13.000000', NULL, 1),
(6826122, 1026071, 141542, '<td valign="top">Perfect.  Looks delectable.</td>', 'Perfect.  Looks delectable.', '2012-07-24 11:08:18.000000', NULL, 1),
(6826124, 1026031, 141542, '<td valign="top">Well.  This looks like it might be tasty, but the way you have photographed it here doesn''t suggest that very much.</td>', 'Well.  This looks like it might be tasty, but the way you have photographed it here doesn''t suggest that very much.', '2012-07-24 11:09:08.000000', NULL, 1),
(6826129, 1026004, 141542, '<td valign="top">I wish the focal point was sharp, but otherwise this is a very interesting image.</td>', 'I wish the focal point was sharp, but otherwise this is a very interesting image.', '2012-07-24 11:10:44.000000', NULL, 1),
(6826132, 1026009, 141542, '<td valign="top">Excellent.</td>', 'Excellent.', '2012-07-24 11:10:55.000000', NULL, 1),
(6826134, 1025920, 141542, '<td valign="top">Something different.</td>', 'Something different.', '2012-07-24 11:11:57.000000', NULL, 1),
(6826140, 1025775, 141542, '<td valign="top">Good!</td>', 'Good!', '2012-07-24 11:13:23.000000', NULL, 1),
(6826142, 1025570, 141542, '<td valign="top">Interesting perspective.</td>', 'Interesting perspective.', '2012-07-24 11:14:01.000000', NULL, 1),
(6826143, 1026021, 141542, '<td valign="top">Excellent image.</td>', 'Excellent image.', '2012-07-24 11:14:23.000000', NULL, 1),
(6826144, 1025606, 141542, '<td valign="top">The darker tones definitely stand out among the high-key, plated dessert, competitors.  Great entry.</td>', 'The darker tones definitely stand out among the high-key, plated dessert, competitors.  Great entry.', '2012-07-24 11:15:22.000000', NULL, 1),
(6826146, 1026030, 141542, '<td valign="top">At all?  et al maybe?  Either way, nothing too exciting here.</td>', 'At all?  et al maybe?  Either way, nothing too exciting here.', '2012-07-24 11:16:39.000000', NULL, 1),
(6826216, 1026009, 103142, '<td valign="top">I like the close up of the shot, but something doesn''t seem quite right... I''m wondering if it''s the highlights on the frosting? -7-</td>', 'I like the close up of the shot, but something doesn''t seem quite right... I''m wondering if it''s the highlights on the frosting? -7-', '2012-07-24 12:57:02.000000', NULL, 1),
(6826217, 1025635, 103142, '<td valign="top">I don''t mind bizarre or out of the box shots, but they have to intrigue me. This is is close, but just doesn''t do it.</td>', 'I don''t mind bizarre or out of the box shots, but they have to intrigue me. This is is close, but just doesn''t do it.', '2012-07-24 12:57:51.000000', NULL, 1),
(6826218, 1025548, 103142, '<td valign="top">Could of different issues here: First, you horizon is a bit tilted, so it looks a bit off kilter. And many times a shot can be better simply by moving your subject farther away from your background. Also, I think your color looks a little off -- the whipped cream has a definite blue tinge to it. Other than that, the dessert looks delicious! :)</td>', 'Could of different issues here: First, you horizon is a bit tilted, so it looks a bit off kilter. And many times a shot can be better simply by moving your subject farther away from your background. Also, I think your color looks a little off -- the whipped cream has a definite blue tinge to it. Other than that, the dessert looks delicious! :)', '2012-07-24 12:59:37.000000', NULL, 1),
(6826219, 1025822, 103142, '<td valign="top">I like the idea, and the look on the face, but the harsh shadows and the wood behind are distracting. I think open shade might have done much better for you. :)</td>', 'I like the idea, and the look on the face, but the harsh shadows and the wood behind are distracting. I think open shade might have done much better for you. :)', '2012-07-24 13:00:34.000000', NULL, 1),
(6826220, 1026068, 103142, '<td valign="top">Love the idea. Not a fan of selective desat, but I think it works here. Your model is great! But, I wish the marshmallow was down more in the shot (I know you don''t want to point an arrow at her, but just bringing it down a bit would make it more part of the shot, imo. Right now, it''s almost an afterthought.<br/> <br/>Fun idea -- -7-</td>', 'Love the idea. Not a fan of selective desat, but I think it works here. Your model is great! But, I wish the marshmallow was down more in the shot (I know you don''t want to point an arrow at her, but just bringing it down a bit would make it more part of the shot, imo. Right now, it''s almost an afterthought. Fun idea -- -7-', '2012-07-24 13:01:56.000000', NULL, 1),
(6826221, 1025994, 103142, '<td valign="top">You model is good and quite lovely, but your setup is bothering me a bit -- the bright spot on the right, the white backdrop not coming down to meet the white floor, plus giving it the feel that your horizon is tilted (or at least the backdrop) distracts from the shot. The rest is lovely. Probably would have been an 8 if the floor and the backdrop lighting/setup was right. 6 as is. (sorry...)</td>', 'You model is good and quite lovely, but your setup is bothering me a bit -- the bright spot on the right, the white backdrop not coming down to meet the white floor, plus giving it the feel that your horizon is tilted (or at least the backdrop) distracts from the shot. The rest is lovely. Probably would have been an 8 if the floor and the backdrop lighting/setup was right. 6 as is. (sorry...)', '2012-07-24 13:04:38.000000', NULL, 1),
(6826222, 1026041, 103142, '<td valign="top">this looks quite underexposed on my screen and the highlights on the front berry are quite bright. If you''re using a flash, have you tried putting something in front of the flash to diffuse it a bit? Or bouncing the flash off a white wall or reflector? If it''s sunlight, hanging a white sheet over your window can help.</td>', 'this looks quite underexposed on my screen and the highlights on the front berry are quite bright. If you''re using a flash, have you tried putting something in front of the flash to diffuse it a bit? Or bouncing the flash off a white wall or reflector? If it''s sunlight, hanging a white sheet over your window can help.', '2012-07-24 13:06:10.000000', NULL, 1),
(6826223, 1025956, 103142, '<td valign="top">Fun idea. I like the tilt.</td>', 'Fun idea. I like the tilt.', '2012-07-24 13:06:37.000000', NULL, 1),
(6826225, 1026049, 103142, '<td valign="top">This is really quite lovely! Nice lighting, fun background. I would have like just a tad softer shadow -- maybe a light reflector on the right... But very nicely done. -8-</td>', 'This is really quite lovely! Nice lighting, fun background. I would have like just a tad softer shadow -- maybe a light reflector on the right... But very nicely done. -8-', '2012-07-24 13:07:45.000000', NULL, 1),
(6826287, 1026071, 114225, '<td valign="top">Decadent! Really like the chosen perspective and tilt. Gives life to the image.</td>', 'Decadent! Really like the chosen perspective and tilt. Gives life to the image.', '2012-07-24 14:10:58.000000', NULL, 1),
(6826295, 1026076, 114225, '<td valign="top">I really want to like this image, but it''s not really doing much for me. I think the choice of coloring is what I don''t like.</td>', 'I really want to like this image, but it''s not really doing much for me. I think the choice of coloring is what I don''t like.', '2012-07-24 14:16:48.000000', NULL, 1),
(6826296, 1025925, 114225, '<td valign="top">Love the focus on the deep red of the cherry.</td>', 'Love the focus on the deep red of the cherry.', '2012-07-24 14:17:07.000000', NULL, 1),
(6826297, 1026053, 114225, '<td valign="top">Looks delicious! I find myself wishing for more depth of field.</td>', 'Looks delicious! I find myself wishing for more depth of field.', '2012-07-24 14:18:43.000000', NULL, 1),
(6826298, 1026010, 114225, '<td valign="top">I find the background here to be stealing a lot of attention away from the desert.</td>', 'I find the background here to be stealing a lot of attention away from the desert.', '2012-07-24 14:19:29.000000', NULL, 1),
(6826299, 1026067, 114225, '<td valign="top">Fantastic use of colors to really highlight the food.</td>', 'Fantastic use of colors to really highlight the food.', '2012-07-24 14:19:55.000000', NULL, 1),
(6826301, 1025993, 114225, '<td valign="top">Really like the action, but even more I like the choice in background color and how it helps the desert stand out.</td>', 'Really like the action, but even more I like the choice in background color and how it helps the desert stand out.', '2012-07-24 14:21:00.000000', NULL, 1),
(6826302, 1026041, 114225, '<td valign="top">There seems to be a blue light cast of this image. To me, if you de-saturated blues to make this a more "warm" image, it would be more inviting.</td>', 'There seems to be a blue light cast of this image. To me, if you de-saturated blues to make this a more "warm" image, it would be more inviting.', '2012-07-24 14:22:10.000000', NULL, 1),
(6826303, 1026070, 43463, '<td valign="top">Voted earlier coming back to comment.<br/> <br/>As an abstract study in shapes and color the image would do far better in an abstract challenge. For a food challenge in which typically one wants to clearly see what we eat (if it looks good it''s fresh....) it suffers from lack of clear identification. Without the title, I cannot clearly tell with 100% accuracy that these are blueberries. When one follows the saying "Show, don''t tell" the imagery is stronger because the audience can readily connect to it. Title should be just icing on the cake (so to speak) and not carry the full weight of telling us what we should be seeing. One thing that throws me off on the blueberries shown here is the color. Only one ''berry'' matches the typical color of purple-blue-black while the others are green and make me think that they are grapes.</td>', 'Voted earlier coming back to comment. As an abstract study in shapes and color the image would do far better in an abstract challenge. For a food challenge in which typically one wants to clearly see what we eat (if it looks good it''s fresh....) it suffers from lack of clear identification. Without the title, I cannot clearly tell with 100% accuracy that these are blueberries. When one follows the saying "Show, don''t tell" the imagery is stronger because the audience can readily connect to it. Title should be just icing on the cake (so to speak) and not carry the full weight of telling us what we should be seeing. One thing that throws me off on the blueberries shown here is the color. Only one ''berry'' matches the typical color of purple-blue-black while the others are green and make me think that they are grapes.', '2012-07-24 14:23:26.000000', NULL, 1),
(6826305, 1026049, 114225, '<td valign="top">Love ginger snaps! I wonder why there are all the lines in the background. If that were more smooth, I think the cookies would pop out more.</td>', 'Love ginger snaps! I wonder why there are all the lines in the background. If that were more smooth, I think the cookies would pop out more.', '2012-07-24 14:23:56.000000', NULL, 1),
(6826306, 1026075, 114225, '<td valign="top">I like the thought behind this image. With a bit more clarity, this could have been killer.</td>', 'I like the thought behind this image. With a bit more clarity, this could have been killer.', '2012-07-24 14:25:00.000000', NULL, 1),
(6826308, 1026059, 114225, '<td valign="top">Wonderful setup of context.</td>', 'Wonderful setup of context.', '2012-07-24 14:27:34.000000', NULL, 1),
(6826309, 1025958, 114225, '<td valign="top">Love the idea, absolutely hate the selective saturation.</td>', 'Love the idea, absolutely hate the selective saturation.', '2012-07-24 14:28:40.000000', NULL, 1),
